```sql
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "public_insert" ON orders FOR INSERT WITH CHECK (true);
CREATE POLICY "public_select" ON orders FOR SELECT USING (true);
CREATE POLICY "public_update" ON orders FOR UPDATE USING (true);
```

If you also get errors like "policy already exists", just skip those — the policies are already in place and everything will work as-is.

```sql
DO $$
BEGIN
  -- Enable RLS if not already enabled
  ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

  -- Insert policy
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'orders' AND policyname = 'public_insert'
  ) THEN
    CREATE POLICY "public_insert" ON orders FOR INSERT WITH CHECK (true);
  END IF;

  -- Select policy
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'orders' AND policyname = 'public_select'
  ) THEN
    CREATE POLICY "public_select" ON orders FOR SELECT USING (true);
  END IF;

  -- Update policy
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'orders' AND policyname = 'public_update'
  ) THEN
    CREATE POLICY "public_update" ON orders FOR UPDATE USING (true);
  END IF;
END $$;
```

This will safely skip any policies that already exist and only create the missing ones.

