'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import RegionMap from './RegionMap'
import FarmersTab from './tabs/FarmersTab'
import BrowseProduceTab from './tabs/BrowseProduceTab'
import AddFarmerTab from './tabs/AddFarmerTab'

const CATEGORY_MAP: Record<string, string[]> = {
  Vegetables: ['Tomato', 'Brinjal', 'Drumstick', 'Bitter Gourd', 'Raw Banana'],
  Fruits: ['Mango', 'Banana', 'Papaya', 'Guava'],
  'Leafy greens': ['Palakura', 'Spinach', 'Methi', 'Coriander'],
}

export default function RegionContent({
  farmers,
  produce,
}: {
  farmers: Record<string, unknown>[]
  produce: Record<string, unknown>[]
}) {
  const { tx } = useLang()
  const [activeFilter, setActiveFilter] = useState('All')
  const [activeTab, setActiveTab] = useState(0)
  const [highlightedFarmerId, setHighlightedFarmerId] = useState<string | null>(null)

  const FILTERS = [tx.all, tx.vegetables, tx.fruits, tx.leafyGreens, tx.naturalOnly]
  const TABS = [tx.farmers, tx.browseProduce, tx.addFarmer]

  // Map filter label back to English key for category lookup
  const filterKeyMap: Record<string, string> = {
    [tx.all]: 'All',
    [tx.vegetables]: 'Vegetables',
    [tx.fruits]: 'Fruits',
    [tx.leafyGreens]: 'Leafy greens',
    [tx.naturalOnly]: 'Natural only',
  }

  const filterKey = filterKeyMap[activeFilter] ?? activeFilter

  const filteredProduce = produce.filter((p) => {
    if (filterKey === 'All') return true
    if (filterKey === 'Natural only') return p.method === 'natural'
    const names = CATEGORY_MAP[filterKey] ?? []
    return names.some((n) => (p.name as string).includes(n))
  })

  const filteredFarmerIds = new Set(filteredProduce.map((p) => p.farmer_id))
  const filteredFarmers = filterKey === 'All'
    ? farmers
    : farmers.filter((f) => filteredFarmerIds.has(f.id))

  return (
    <div>
      {/* Filter chips */}
      <div className="bg-white border-b border-gray-100 px-4 py-3">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide">
          {FILTERS.map((filter) => (
            <button
              key={filter}
              onClick={() => setActiveFilter(filter)}
              className={`flex-shrink-0 px-4 py-1.5 rounded-full text-sm font-semibold border transition-all ${
                activeFilter === filter
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-white text-gray-600 border-gray-200'
              }`}
            >
              {filter}
            </button>
          ))}
        </div>
      </div>

      {/* SVG Map */}
      <RegionMap
        farmers={filteredFarmers}
        highlightedFarmerId={highlightedFarmerId}
        onPinClick={setHighlightedFarmerId}
      />

      {/* Tabs */}
      <div className="sticky top-0 z-40 bg-white border-b border-gray-200">
        <div className="flex">
          {TABS.map((tab, i) => (
            <button
              key={tab}
              onClick={() => setActiveTab(i)}
              className={`flex-1 py-3 text-xs font-semibold border-b-2 transition-colors ${
                activeTab === i
                  ? 'border-green-700 text-green-700'
                  : 'border-transparent text-gray-500'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 py-4">
        {activeTab === 0 && (
          <FarmersTab
            farmers={filteredFarmers}
            produce={produce}
            highlightedFarmerId={highlightedFarmerId}
          />
        )}
        {activeTab === 1 && <BrowseProduceTab produce={filteredProduce} farmers={farmers} />}
        {activeTab === 2 && <AddFarmerTab farmerCount={farmers.length} />}
      </div>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'

type Farmer = {
  id: string
  slug: string
  name: string
  village?: string
  district?: string
  method?: string
  rating_avg?: number
  farming_since_year?: number
}

type Produce = {
  farmer_id: string
  name: string
  emoji?: string
}

export default function FarmersTab({
  farmers,
  produce,
  highlightedFarmerId,
}: {
  farmers: Record<string, unknown>[]
  produce: Record<string, unknown>[]
  highlightedFarmerId: string | null
}) {
  const { tx } = useLang()
  const list = farmers as Farmer[]
  const produceList = produce as Produce[]

  if (list.length === 0) {
    return <div className="text-center py-10 text-gray-400 text-sm">{tx.noFarmersFound}</div>
  }

  return (
    <div className="space-y-3">
      {list.map((farmer, index) => {
        const farmerProduce = produceList.filter((p) => p.farmer_id === farmer.id)
        const isHighlighted = highlightedFarmerId === farmer.id
        const isCofounder = index === 0
        const initials = farmer.name.slice(0, 2).toUpperCase()
        const yearsfarming = farmer.farming_since_year
          ? new Date().getFullYear() - farmer.farming_since_year
          : null

        return (
          <div key={farmer.id}
            className={`bg-white rounded-xl border p-4 transition-all ${
              isHighlighted ? 'border-green-500 shadow-md' : 'border-gray-100'
            } ${isCofounder ? 'border-l-4 border-l-green-600' : ''}`}
          >
            <div className="flex items-start gap-3">
              <div className="w-11 h-11 rounded-full bg-green-700 flex items-center justify-center text-white font-bold flex-shrink-0">
                {initials}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <h3 className="font-bold text-gray-900 text-sm">{farmer.name}</h3>
                  {isCofounder && (
                    <span className="bg-amber-100 text-amber-800 text-[10px] font-bold px-2 py-0.5 rounded-full">
                      {tx.cofounder}
                    </span>
                  )}
                  {farmer.rating_avg === 0 && (
                    <span className="bg-blue-100 text-blue-700 text-[10px] font-bold px-2 py-0.5 rounded-full">
                      {tx.newFarmer}
                    </span>
                  )}
                </div>
                <p className="text-xs text-gray-500 mt-0.5">
                  {farmer.village ?? farmer.district}
                  {yearsfarming ? ` · ${yearsfarming} ${tx.yrsFarming}` : ''}
                </p>

                {farmerProduce.length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-2">
                    {farmerProduce.slice(0, 4).map((p) => (
                      <span key={p.name} className="bg-green-50 text-green-800 text-[10px] font-semibold px-2 py-0.5 rounded-full">
                        {p.emoji ?? '🌿'} {p.name}
                      </span>
                    ))}
                    {farmerProduce.length > 4 && (
                      <span className="text-[10px] text-gray-400">+{farmerProduce.length - 4} more</span>
                    )}
                  </div>
                )}

                <div className="flex items-center justify-between mt-3">
                  <div className="flex items-center gap-2">
                    {farmer.method === 'natural' && (
                      <span className="bg-green-100 text-green-800 text-[10px] font-bold px-2 py-0.5 rounded-full">
                        {tx.naturalFarming}
                      </span>
                    )}
                    {farmer.rating_avg ? (
                      <span className="text-xs text-gray-600">⭐ {farmer.rating_avg}</span>
                    ) : null}
                  </div>
                  <Link href={`/farmer/${farmer.slug}`}
                    className="bg-green-700 text-white text-xs font-semibold px-4 py-2 rounded-lg">
                    {tx.viewShop}
                  </Link>
                </div>
              </div>
            </div>
          </div>
        )
      })}

      <div className="border-2 border-dashed border-gray-200 rounded-xl p-4 text-center">
        <p className="text-sm font-semibold text-gray-600">{tx.knowAFarmer}</p>
        <p className="text-xs text-gray-400 mt-1">{tx.helpThemReach}</p>
        <button
          onClick={() => {
            const tab = document.querySelectorAll('button[class*="border-b-2"]')
            if (tab[2]) (tab[2] as HTMLButtonElement).click()
          }}
          className="mt-3 bg-green-50 text-green-700 border border-green-600 text-sm font-semibold px-4 py-2 rounded-lg"
        >
          {tx.addFarmerCta}
        </button>
      </div>
    </div>
  )
}

import Link from 'next/link'

type Produce = {
  id: string
  name: string
  variety?: string
  emoji?: string
  farmer_id: string
  price_tier_1_price?: number
  unit?: string
  stock_qty?: number
  method?: string
}

type Farmer = {
  id: string
  slug: string
  name: string
  village?: string
}

export default function BrowseProduceTab({
  produce,
  farmers,
}: {
  produce: Record<string, unknown>[]
  farmers: Record<string, unknown>[]
}) {
  const list = produce as Produce[]
  const farmerList = farmers as Farmer[]

  const getFarmer = (farmerId: string) =>
    farmerList.find((f) => f.id === farmerId)

  if (list.length === 0) {
    return (
      <div className="text-center py-10 text-gray-400 text-sm">
        No produce found for this filter.
      </div>
    )
  }

  return (
    <div className="grid grid-cols-2 gap-3">
      {list.map((item) => {
        const farmer = getFarmer(item.farmer_id)
        if (!farmer) return null

        return (
          <Link
            key={item.id}
            href={`/farmer/${farmer.slug}#produce`}
            className="bg-white rounded-xl border border-gray-100 p-3 block"
          >
            <div className="text-3xl mb-2">{item.emoji ?? '🌿'}</div>
            <h3 className="text-sm font-bold text-gray-900 leading-tight">{item.name}</h3>
            {item.variety && (
              <p className="text-[10px] text-gray-500 mt-0.5">{item.variety}</p>
            )}
            <p className="text-xs text-green-700 font-semibold mt-1">
              {farmer.name} · {farmer.village}
            </p>
            <div className="flex items-center justify-between mt-2">
              {item.price_tier_1_price && (
                <span className="text-sm font-bold text-gray-900">
                  ₹{item.price_tier_1_price}/{item.unit ?? 'kg'}
                </span>
              )}
              {item.method === 'natural' && (
                <span className="bg-green-100 text-green-800 text-[10px] font-bold px-2 py-0.5 rounded-full">
                  Natural
                </span>
              )}
            </div>
            {item.stock_qty !== undefined && item.stock_qty > 0 && (
              <p className="text-[10px] text-gray-400 mt-1">{item.stock_qty} kg available</p>
            )}
          </Link>
        )
      })}
    </div>
  )
}

'use client'

